use super::*;

/// The body `id` had at `rev` on main, if that rev exists and is not a tombstone.
pub(crate) fn body_at(conn: &Connection, id: &str, rev: i64) -> Result<Option<Value>, String> {
    let text: Option<String> = conn
        .query_row(
            "SELECT json FROM record_revs WHERE id = ?1 AND lane = 'main' AND rev = ?2",
            params![id, rev],
            |r| r.get(0),
        )
        .ok()
        .flatten();
    match text {
        None => Ok(None),
        Some(t) => serde_json::from_str(&t).map(Some).map_err(|e| format!("rev {rev} of '{id}': {e}")),
    }
}
